return [{
  json: {
    trace_id: start.trace_id,
    trace_url: start.trace_url,
    completeBody: {
      status: 'completed',
      summary: `Starter run with ${nodes.length} packed step(s)`,
      execution: {
        workflow_name: $workflow.name,
        execution_id: String($execution.id),
        nodes,
      },
    },
  },
}];

const done = $input.first().json;
return [{
  json: {
    status: done.status,
    trace_id: done.trace_id,
    trace_url: done.trace_url,
    events: (done.events || []).length,
    note: 'Open trace_url in Aegis Console to replay the signed timeline.',
